insert into public.rules (id, market_code, category, rule_key, kind, title, fix, params, applies_if, severity, citation, confidence, version)
values
  ('eu.supplements.daily-dose', 'EU', 'supplements', 'daily-dose', 'required_field', 'The recommended daily dose is not stated', 'State the portion recommended for daily consumption, e.g. "Take 2 capsules a day".', '{"facts":["daily_dose"]}'::jsonb, null, 'needs_attention', '{"regulation":"Directive 2002/46/EC (food supplements)","article":"Art. 6(3)(b)","url":"https://eur-lex.europa.eu/eli/dir/2002/46/oj","effective_from":"2002-07-12"}'::jsonb, 'drafted', 1),
  ('eu.supplements.date-of-minimum-durability', 'EU', 'supplements', 'date-of-minimum-durability', 'required_field', 'No date of minimum durability ("best before")', 'Print a best-before date on the pack.', '{"facts":["best_before"]}'::jsonb, null, 'needs_attention', '{"regulation":"Regulation (EU) No 1169/2011 (food information to consumers)","article":"Art. 9(1)(f)","url":"https://eur-lex.europa.eu/eli/reg/2011/1169/oj","effective_from":"2014-12-13"}'::jsonb, 'drafted', 1),
  ('eu.supplements.de-notification', 'EU', 'supplements', 'de-notification', 'registration', 'Germany: notify the BVL before first placing on the market', 'Submit the product notification to the BVL, with a label sample, before first selling in Germany.', '{"action":"Notify the Federal Office of Consumer Protection and Food Safety (BVL)","url":"https://www.bvl.bund.de/"}'::jsonb, null, 'advisory', '{"regulation":"Nahrungsergänzungsmittelverordnung (NemV)","article":"§ 5","url":"https://www.gesetze-im-internet.de/nemv/__5.html","effective_from":"2004-05-28"}'::jsonb, 'drafted', 1),
  ('eu.supplements.designation-food-supplement', 'EU', 'supplements', 'designation-food-supplement', 'warning_text', 'The product is not sold under the name "food supplement"', 'Print the legal name "food supplement" on the label in each label language (de: Nahrungsergänzungsmittel, fr: complément alimentaire). A brand or fancy name may appear as well, but does not replace it.', '{"texts":{"en":"food supplement","de":"Nahrungsergänzungsmittel","fr":"complément alimentaire"}}'::jsonb, null, 'needs_attention', '{"regulation":"Directive 2002/46/EC (food supplements)","article":"Art. 6(1)","url":"https://eur-lex.europa.eu/eli/dir/2002/46/oj","effective_from":"2002-07-12"}'::jsonb, 'drafted', 1),
  ('eu.supplements.disease-claims', 'EU', 'supplements', 'disease-claims', 'claim', 'The copy attributes disease-preventing or curing properties to the product', 'Remove wording that says the product prevents, treats or cures a disease. Health claims must be on the EU register of authorised claims and worded as authorised.', '{"phrases":["cures","cure for","treats","heals","prevents disease","anti-cancer","heilt","guérit"]}'::jsonb, null, 'needs_attention', '{"regulation":"Regulation (EU) No 1169/2011 (food information to consumers)","article":"Art. 7(3)","url":"https://eur-lex.europa.eu/eli/reg/2011/1169/oj","effective_from":"2014-12-13"}'::jsonb, 'drafted', 1),
  ('eu.supplements.label-language', 'EU', 'supplements', 'label-language', 'language', 'The label is not in a language of the v1 EU language packs', 'Mandatory information must be in a language easily understood where the product is sold. Add German for Germany and Austria, French for France and Belgium (French-speaking).', '{"languages":["de","fr"],"mode":"any"}'::jsonb, null, 'blocked', '{"regulation":"Regulation (EU) No 1169/2011 (food information to consumers)","article":"Art. 15(1)","url":"https://eur-lex.europa.eu/eli/reg/2011/1169/oj","effective_from":"2014-12-13"}'::jsonb, 'drafted', 1),
  ('eu.supplements.lot-marking', 'EU', 'supplements', 'lot-marking', 'required_field', 'No lot or batch identification', 'Print a lot or batch code on the pack, preceded by "L" unless clearly distinguishable.', '{"facts":["batch_code"]}'::jsonb, null, 'needs_attention', '{"regulation":"Directive 2011/91/EU (indications or marks identifying the lot)","article":"Art. 2 and 4","url":"https://eur-lex.europa.eu/eli/dir/2011/91/oj","effective_from":"2011-12-16"}'::jsonb, 'drafted', 1),
  ('eu.supplements.net-quantity', 'EU', 'supplements', 'net-quantity', 'required_field', 'The net quantity is not stated', 'State the net quantity (for capsules and tablets, the number of units and their weight as applicable).', '{"facts":["net_quantity"]}'::jsonb, null, 'needs_attention', '{"regulation":"Regulation (EU) No 1169/2011 (food information to consumers)","article":"Art. 9(1)(e)","url":"https://eur-lex.europa.eu/eli/reg/2011/1169/oj","effective_from":"2014-12-13"}'::jsonb, 'drafted', 1),
  ('eu.supplements.prohibited-ephedra', 'EU', 'supplements', 'prohibited-ephedra', 'prohibited_substance', 'Contains ephedra, which may not be added to foods in the EU', 'Remove ephedra herb and its preparations from the formulation before selling in the EU.', '{"substances":[{"name":"ephedra","aliases":["ephedra sinica","ma huang","ephedrine alkaloids"]}]}'::jsonb, null, 'blocked', '{"regulation":"Regulation (EC) No 1925/2006, Annex III Part A, as amended by Regulation (EU) 2019/650","article":"Art. 8 and Annex III Part A","url":"https://eur-lex.europa.eu/eli/reg/2019/650/oj","effective_from":"2019-05-14"}'::jsonb, 'drafted', 1),
  ('eu.supplements.responsible-food-business-operator', 'EU', 'supplements', 'responsible-food-business-operator', 'required_field', 'No EU food business operator name and address', 'Name the food business operator responsible for the product in the EU and give their address. A business outside the EU needs an EU-based operator or importer under whose name the product is marketed.', '{"facts":["responsible_person_name","responsible_person_address"]}'::jsonb, null, 'blocked', '{"regulation":"Regulation (EU) No 1169/2011 (food information to consumers)","article":"Art. 8(1) and 9(1)(h)","url":"https://eur-lex.europa.eu/eli/reg/2011/1169/oj","effective_from":"2014-12-13"}'::jsonb, 'drafted', 1),
  ('eu.supplements.vitamin-d-de-maximum', 'EU', 'supplements', 'vitamin-d-de-maximum', 'limit', 'Vitamin D above the German recommended maximum for supplements', 'For Germany, consider reducing vitamin D to at most 20 µg per daily dose. This is a national recommendation, not EU law; other member states differ.', '{"nutrient":"vitamin d","aliases":["cholecalciferol","vitamin d3","ergocalciferol","vitamin d2"],"max":20,"unit":"µg"}'::jsonb, null, 'advisory', '{"regulation":"BfR, Updated maximum level proposals for vitamins and minerals in food supplements (2021)","article":"Vitamin D","url":"https://www.bfr.bund.de/en/","effective_from":"2021-03-15"}'::jsonb, 'needs_review', 1),
  ('eu.supplements.warning-do-not-exceed', 'EU', 'supplements', 'warning-do-not-exceed', 'warning_text', 'The "do not exceed the recommended daily dose" warning is missing', 'Add the warning not to exceed the stated recommended daily dose, in each label language.', '{"texts":{"en":"Do not exceed the recommended daily dose.","de":"Die angegebene empfohlene tägliche Verzehrsmenge darf nicht überschritten werden.","fr":"Ne pas dépasser la dose journalière recommandée."}}'::jsonb, null, 'needs_attention', '{"regulation":"Directive 2002/46/EC (food supplements)","article":"Art. 6(3)(c)","url":"https://eur-lex.europa.eu/eli/dir/2002/46/oj","effective_from":"2002-07-12"}'::jsonb, 'drafted', 1),
  ('eu.supplements.warning-varied-diet', 'EU', 'supplements', 'warning-varied-diet', 'warning_text', 'The "not a substitute for a varied diet" statement is missing', 'Add the statement that food supplements should not be used as a substitute for a varied diet, in each label language.', '{"texts":{"en":"Food supplements should not be used as a substitute for a varied and balanced diet and a healthy lifestyle.","de":"Nahrungsergänzungsmittel sind kein Ersatz für eine ausgewogene und abwechslungsreiche Ernährung und eine gesunde Lebensweise.","fr":"Les compléments alimentaires ne doivent pas être utilisés comme substituts d''un régime alimentaire varié et équilibré et d''un mode de vie sain."}}'::jsonb, null, 'needs_attention', '{"regulation":"Directive 2002/46/EC (food supplements)","article":"Art. 6(3)(d)","url":"https://eur-lex.europa.eu/eli/dir/2002/46/oj","effective_from":"2002-07-12"}'::jsonb, 'drafted', 1),
  ('eu.supplements.warning-young-children', 'EU', 'supplements', 'warning-young-children', 'warning_text', 'The "out of reach of young children" statement is missing', 'Add the statement that the product should be stored out of the reach of young children, in each label language.', '{"texts":{"en":"Store out of the reach of young children.","de":"Für kleine Kinder unzugänglich aufbewahren.","fr":"Tenir hors de portée des jeunes enfants."}}'::jsonb, null, 'needs_attention', '{"regulation":"Directive 2002/46/EC (food supplements)","article":"Art. 6(3)(e)","url":"https://eur-lex.europa.eu/eli/dir/2002/46/oj","effective_from":"2002-07-12"}'::jsonb, 'drafted', 1),
  ('uk.supplements.daily-dose', 'UK', 'supplements', 'daily-dose', 'required_field', 'The recommended daily dose is not stated', 'State the portion recommended for daily consumption, e.g. "Take 2 capsules a day".', '{"facts":["daily_dose"]}'::jsonb, null, 'needs_attention', '{"regulation":"The Food Supplements (England) Regulations 2003 (SI 2003/1387)","article":"reg. 6","url":"https://www.legislation.gov.uk/uksi/2003/1387/regulation/6","effective_from":"2003-08-01"}'::jsonb, 'drafted', 1),
  ('uk.supplements.date-of-minimum-durability', 'UK', 'supplements', 'date-of-minimum-durability', 'required_field', 'No date of minimum durability ("best before")', 'Print a best-before date on the pack.', '{"facts":["best_before"]}'::jsonb, null, 'needs_attention', '{"regulation":"Regulation (EU) No 1169/2011 as it applies in Great Britain (assimilated law)","article":"Art. 9(1)(f)","url":"https://www.legislation.gov.uk/eur/2011/1169/contents","effective_from":"2014-12-13"}'::jsonb, 'drafted', 1),
  ('uk.supplements.designation-food-supplement', 'UK', 'supplements', 'designation-food-supplement', 'warning_text', 'The product is not sold under the name "food supplement"', 'Print the name "food supplement" on the label. A brand name may appear as well but does not replace it.', '{"texts":{"en":"food supplement"}}'::jsonb, null, 'needs_attention', '{"regulation":"The Food Supplements (England) Regulations 2003 (SI 2003/1387)","article":"reg. 6","url":"https://www.legislation.gov.uk/uksi/2003/1387/regulation/6","effective_from":"2003-08-01"}'::jsonb, 'drafted', 1),
  ('uk.supplements.disease-claims', 'UK', 'supplements', 'disease-claims', 'claim', 'The copy attributes disease-preventing or curing properties to the product', 'Remove wording that says the product prevents, treats or cures a disease. Health claims must be on the GB nutrition and health claims register and worded as authorised.', '{"phrases":["cures","cure for","treats","heals","prevents disease","anti-cancer"]}'::jsonb, null, 'needs_attention', '{"regulation":"Regulation (EU) No 1169/2011 as it applies in Great Britain (assimilated law)","article":"Art. 7(3)","url":"https://www.legislation.gov.uk/eur/2011/1169/contents","effective_from":"2014-12-13"}'::jsonb, 'drafted', 1),
  ('uk.supplements.label-language', 'UK', 'supplements', 'label-language', 'language', 'The label is not in English', 'Give all mandatory information in English.', '{"languages":["en"],"mode":"all"}'::jsonb, null, 'blocked', '{"regulation":"Regulation (EU) No 1169/2011 as it applies in Great Britain (assimilated law)","article":"Art. 15(1)","url":"https://www.legislation.gov.uk/eur/2011/1169/contents","effective_from":"2014-12-13"}'::jsonb, 'drafted', 1),
  ('uk.supplements.lot-marking', 'UK', 'supplements', 'lot-marking', 'required_field', 'No lot or batch identification', 'Print a lot or batch code on the pack.', '{"facts":["batch_code"]}'::jsonb, null, 'needs_attention', '{"regulation":"The Food (Lot Marking) Regulations 1996 (SI 1996/1502)","article":"reg. 3","url":"https://www.legislation.gov.uk/uksi/1996/1502/contents","effective_from":"1996-07-01"}'::jsonb, 'drafted', 1),
  ('uk.supplements.net-quantity', 'UK', 'supplements', 'net-quantity', 'required_field', 'The net quantity is not stated', 'State the net quantity (for capsules and tablets, the number of units and their weight as applicable).', '{"facts":["net_quantity"]}'::jsonb, null, 'needs_attention', '{"regulation":"Regulation (EU) No 1169/2011 as it applies in Great Britain (assimilated law)","article":"Art. 9(1)(e)","url":"https://www.legislation.gov.uk/eur/2011/1169/contents","effective_from":"2014-12-13"}'::jsonb, 'drafted', 1),
  ('uk.supplements.prohibited-ephedra', 'UK', 'supplements', 'prohibited-ephedra', 'prohibited_substance', 'Contains ephedra, which may not be added to foods in Great Britain', 'Remove ephedra herb and its preparations from the formulation before selling in Great Britain.', '{"substances":[{"name":"ephedra","aliases":["ephedra sinica","ma huang","ephedrine alkaloids"]}]}'::jsonb, null, 'blocked', '{"regulation":"Regulation (EC) No 1925/2006 as it applies in Great Britain, Annex III Part A","article":"Art. 8 and Annex III Part A","url":"https://www.legislation.gov.uk/eur/2006/1925/annex/III","effective_from":"2019-05-14"}'::jsonb, 'drafted', 1),
  ('uk.supplements.uk-food-business-operator', 'UK', 'supplements', 'uk-food-business-operator', 'required_field', 'No UK food business operator name and address', 'Name the food business operator responsible for the product and give a UK address. For Great Britain an EU-only address is no longer enough.', '{"facts":["responsible_person_name","responsible_person_address"]}'::jsonb, null, 'blocked', '{"regulation":"Regulation (EU) No 1169/2011 as it applies in Great Britain (assimilated law)","article":"Art. 8(1) and 9(1)(h)","url":"https://www.legislation.gov.uk/eur/2011/1169/contents","effective_from":"2014-12-13"}'::jsonb, 'drafted', 1),
  ('uk.supplements.warning-do-not-exceed', 'UK', 'supplements', 'warning-do-not-exceed', 'warning_text', 'The "do not exceed the recommended daily dose" warning is missing', 'Add a warning not to exceed the stated recommended daily dose.', '{"texts":{"en":"Do not exceed the recommended daily dose."}}'::jsonb, null, 'needs_attention', '{"regulation":"The Food Supplements (England) Regulations 2003 (SI 2003/1387)","article":"reg. 6","url":"https://www.legislation.gov.uk/uksi/2003/1387/regulation/6","effective_from":"2003-08-01"}'::jsonb, 'drafted', 1),
  ('uk.supplements.warning-varied-diet', 'UK', 'supplements', 'warning-varied-diet', 'warning_text', 'The "not a substitute for a varied diet" statement is missing', 'Add a statement that food supplements should not be used as a substitute for a varied diet.', '{"texts":{"en":"Food supplements should not be used as a substitute for a varied and balanced diet and a healthy lifestyle."}}'::jsonb, null, 'needs_attention', '{"regulation":"The Food Supplements (England) Regulations 2003 (SI 2003/1387)","article":"reg. 6","url":"https://www.legislation.gov.uk/uksi/2003/1387/regulation/6","effective_from":"2003-08-01"}'::jsonb, 'drafted', 1),
  ('uk.supplements.warning-young-children', 'UK', 'supplements', 'warning-young-children', 'warning_text', 'The "out of reach of young children" statement is missing', 'Add a statement that the product should be stored out of the reach of young children.', '{"texts":{"en":"Store out of the reach of young children."}}'::jsonb, null, 'needs_attention', '{"regulation":"The Food Supplements (England) Regulations 2003 (SI 2003/1387)","article":"reg. 6","url":"https://www.legislation.gov.uk/uksi/2003/1387/regulation/6","effective_from":"2003-08-01"}'::jsonb, 'drafted', 1),
  ('us.supplements.adverse-event-contact', 'US', 'supplements', 'adverse-event-contact', 'required_field', 'No domestic address or phone number for adverse event reports', 'Add a US address or US phone number through which the responsible person can receive serious adverse event reports.', '{"facts":["adverse_event_contact"]}'::jsonb, null, 'needs_attention', '{"regulation":"Federal Food, Drug, and Cosmetic Act § 403(y) (21 U.S.C. 343(y))","article":"§ 403(y)","url":"https://www.law.cornell.edu/uscode/text/21/343","effective_from":"2007-12-22"}'::jsonb, 'drafted', 1),
  ('us.supplements.disease-claims', 'US', 'supplements', 'disease-claims', 'claim', 'The copy makes a disease claim', 'Remove wording that says the product diagnoses, treats, cures, mitigates or prevents a disease. A dietary supplement may make structure/function claims only, with the FDA disclaimer.', '{"phrases":["cures","cure for","treats","heals","prevents disease","anti-cancer","lowers blood pressure","reverses diabetes"]}'::jsonb, null, 'needs_attention', '{"regulation":"21 CFR Part 101","article":"§ 101.93(g)","url":"https://www.ecfr.gov/current/title-21/chapter-I/subchapter-B/part-101","effective_from":"1994-10-25"}'::jsonb, 'drafted', 1),
  ('us.supplements.fda-food-facility-registration', 'US', 'supplements', 'fda-food-facility-registration', 'registration', 'The manufacturing facility must be registered with FDA', 'Confirm the facility that manufactures, packs or holds the product is registered with FDA (renewed every even-numbered year).', '{"action":"Confirm food facility registration with FDA","url":"https://www.fda.gov/food/online-registration-food-facilities"}'::jsonb, null, 'advisory', '{"regulation":"21 CFR Part 1, Subpart H","article":"§ 1.225","url":"https://www.ecfr.gov/current/title-21/chapter-I/subchapter-A/part-1/subpart-H","effective_from":"2003-12-12"}'::jsonb, 'drafted', 1),
  ('us.supplements.iron-warning', 'US', 'supplements', 'iron-warning', 'warning_text', 'An iron-containing product without the accidental-overdose warning', 'Add the iron accidental-overdose warning exactly as worded.', '{"texts":{"en":"WARNING: Accidental overdose of iron-containing products is a leading cause of fatal poisoning in children under 6. Keep this product out of reach of children. In case of accidental overdose, call a doctor or poison control center immediately."}}'::jsonb, '{"ingredient_any":["iron","ferrous","ferric"]}'::jsonb, 'blocked', '{"regulation":"21 CFR Part 101","article":"§ 101.17(e)","url":"https://www.ecfr.gov/current/title-21/chapter-I/subchapter-B/part-101","effective_from":"1994-10-25"}'::jsonb, 'drafted', 1),
  ('us.supplements.label-language', 'US', 'supplements', 'label-language', 'language', 'The label is not in English', 'Give all required label information in English (Puerto Rico may use Spanish).', '{"languages":["en"],"mode":"all"}'::jsonb, null, 'blocked', '{"regulation":"21 CFR Part 101","article":"§ 101.15(c)","url":"https://www.ecfr.gov/current/title-21/chapter-I/subchapter-B/part-101","effective_from":"1994-10-25"}'::jsonb, 'drafted', 1),
  ('us.supplements.manufacturer-name-and-place', 'US', 'supplements', 'manufacturer-name-and-place', 'required_field', 'No name and place of business of the manufacturer, packer or distributor', 'Give the name and place of business (city, state and ZIP) of the manufacturer, packer or distributor.', '{"facts":["manufacturer_name","manufacturer_address"]}'::jsonb, null, 'needs_attention', '{"regulation":"21 CFR Part 101","article":"§ 101.5","url":"https://www.ecfr.gov/current/title-21/chapter-I/subchapter-B/part-101","effective_from":"1994-10-25"}'::jsonb, 'drafted', 1),
  ('us.supplements.net-quantity', 'US', 'supplements', 'net-quantity', 'required_field', 'The net quantity of contents is not stated', 'State the net quantity of contents on the principal display panel (count, weight or measure).', '{"facts":["net_quantity"]}'::jsonb, null, 'needs_attention', '{"regulation":"21 CFR Part 101","article":"§ 101.105","url":"https://www.ecfr.gov/current/title-21/chapter-I/subchapter-B/part-101","effective_from":"1994-10-25"}'::jsonb, 'drafted', 1),
  ('us.supplements.prohibited-ephedrine-alkaloids', 'US', 'supplements', 'prohibited-ephedrine-alkaloids', 'prohibited_substance', 'Contains ephedrine alkaloids, which make a dietary supplement adulterated', 'Remove ephedra and ephedrine alkaloids from the formulation before selling in the US.', '{"substances":[{"name":"ephedrine alkaloids","aliases":["ephedra","ephedra sinica","ma huang","ephedrine"]}]}'::jsonb, null, 'blocked', '{"regulation":"21 CFR Part 119","article":"§ 119.1","url":"https://www.ecfr.gov/current/title-21/chapter-I/subchapter-B/part-119","effective_from":"2004-04-12"}'::jsonb, 'drafted', 1),
  ('us.supplements.statement-of-identity', 'US', 'supplements', 'statement-of-identity', 'warning_text', 'The statement of identity does not say "dietary supplement"', 'Identify the product as a "dietary supplement" on the principal display panel. "Supplement" may replace "dietary" with the name of the dietary ingredient (e.g. "vitamin C supplement") — confirm the wording with counsel.', '{"texts":{"en":"dietary supplement"}}'::jsonb, null, 'needs_attention', '{"regulation":"21 CFR Part 101","article":"§ 101.3(g)","url":"https://www.ecfr.gov/current/title-21/chapter-I/subchapter-B/part-101","effective_from":"1994-10-25"}'::jsonb, 'drafted', 1),
  ('us.supplements.structure-function-disclaimer', 'US', 'supplements', 'structure-function-disclaimer', 'warning_text', 'Structure/function claims are made without the FDA disclaimer', 'Wherever a structure/function claim appears, add the disclaimer, linked to the claim by a symbol if it is not adjacent.', '{"texts":{"en":"This statement has not been evaluated by the Food and Drug Administration. This product is not intended to diagnose, treat, cure, or prevent any disease."}}'::jsonb, '{"fact_present":"claims"}'::jsonb, 'needs_attention', '{"regulation":"21 CFR Part 101","article":"§ 101.93(b)–(c)","url":"https://www.ecfr.gov/current/title-21/chapter-I/subchapter-B/part-101","effective_from":"1994-10-25"}'::jsonb, 'drafted', 1),
  ('us.supplements.supplement-facts', 'US', 'supplements', 'supplement-facts', 'required_field', 'No Supplement Facts panel', 'Add a Supplement Facts panel in the format FDA prescribes.', '{"facts":["nutrition_panel"]}'::jsonb, null, 'blocked', '{"regulation":"21 CFR Part 101","article":"§ 101.36","url":"https://www.ecfr.gov/current/title-21/chapter-I/subchapter-B/part-101","effective_from":"1994-10-25"}'::jsonb, 'drafted', 1)
